args.sql:
SELECT SUM(
    REPLACE(REPLACE(op.revloss, '$', ''), ',', '')::numeric
) AS total_loss
FROM mechanical_condition mc
JOIN operational_metrics op ON mc.snapmk = op.snapops
WHERE mc.mech_health_snapshot->'electrical_integrity'->>'grounding_status' = 'Failed';

